/**
 * Arabic text generated by the backend (backend/src services, config and seeds): error
 * messages, notification titles, ledger descriptions and seeded labels. The UI shows it
 * through translateData(); SERVER_PATTERNS covers messages that embed values.
 */

const COURSE_STATUS = {
  draft: 'Draft',
  planned: 'Planned',
  enrollment_open: 'Enrollment open',
  active: 'Active',
  completed: 'Completed',
  archived: 'Archived',
};

const count = (n, one, many) => `${n} ${Number(n) === 1 ? one : many}`;

export const SERVER_PATTERNS = [
  // Lead status change with a reason: "new → interested: <reason>" (status codes stay as the Arabic UI shows them)
  [/^([a-z_]+) → ([a-z_]+): (.+)$/s, (m, translateData) => `${m[1]} → ${m[2]}: ${translateData(m[3])}`],
  [/^الرسالة أطول من (\d+) حرفاً$/, (m) => `The message is longer than ${m[1]} characters.`],
  [/^جلسة (\d+) — (.+)$/s, (m) => `Session ${m[1]} — ${m[2]}`],
  [/^تم إرسال طلب سلفة بمبلغ (\d+)$/, (m) => `An advance request for ${Number(m[1]).toLocaleString('en-US')} was sent.`],
  [/^(.+) طلب سلفة$/, (m) => `${m[1]} requested a salary advance`],
  [/^تعارض في جدول المدرب مع جلسة في دورة «(.+)»$/, (m) => `The instructor's schedule conflicts with a session in “${m[1]}”.`],
  [/^راتب (\d{4}-\d{2})$/, (m) => `Salary ${m[1]}`],
  [/^متابعة مجدولة: (.+)$/, (m) => `Follow-up scheduled: ${m[1]}`],
  [
    /^لا يمكن التسجيل في دورة بحالة «(.+)» — يجب أن تكون مفتوحة للتسجيل أو نشطة$/,
    (m) => `Can't enroll in a course with status “${COURSE_STATUS[m[1]] || m[1]}” — it must be open for enrollment or active.`,
  ],
  [/^تسجيل في دورة «(.+)»( \+ دفعة)?$/, (m) => `Enrolled in “${m[1]}”${m[2] ? ' + payment' : ''}`],
  [/^الدورة ممتلئة \(السعة (\d+)\)$/, (m) => `The course is full (capacity ${m[1]}).`],
  [
    /^تم إنشاء روابط تقييم لـ «(.+)»\. يمكن نسخها من صفحة الدورة\.$/,
    (m) => `Evaluation links were created for “${m[1]}”. You can copy them from the course page.`,
  ],
  [/^لا يمكن حذف المصدر لوجود (\d+) عميل مرتبط به$/, (m) => `Can't delete this source: ${count(m[1], 'lead is', 'leads are')} linked to it.`],
  [/^مجموع نسب الشركاء لا يجوز أن يتجاوز 100٪ \(سيصبح (.+)\)$/, (m) => `Partner shares can't exceed 100% in total (it would be ${m[1]}%).`],
  [/^لا يمكن حذف البند لوجود (\d+) مهمة مرتبطة به$/, (m) => `Can't delete this item: ${count(m[1], 'task is', 'tasks are')} linked to it.`],
  [/^(.+) — غير محدد$/, (m) => `${m[1]} — Not specified`],
  // Website chats: lead activity and the fallback visitor name in a notification body
  [/^تحدث مع بوت الموقع \((.+)\)$/, (m) => `Talked to the website bot (${m[1]})`],
  [/^زائر من الموقع — (.+)$/s, (m) => `Website visitor — ${m[1]}`],
];

